// src/darkMode.js

function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

function applyTheme(isDark) {
    if (isDark) {
        document.body.classList.add("dark");
    } else {
        document.body.classList.remove("dark");
    }
}

export function addEventListener() {
    let toggle = document.getElementById("darkModeToggle");
    // Wait for the element to be available
    while (!toggle) {
        toggle = document.getElementById("darkModeToggle");
        sleep(50);
    }
    let isDark = localStorage.getItem("isDark");
    // Create default if not exists
    if (isDark === null) {
        isDark = "false";
        localStorage.setItem("isDark", isDark);
    }
    isDark = isDark === "true";
    // Add event handler for toggle
    toggle.addEventListener("change", () => {
        isDark = toggle.checked;
        localStorage.setItem("isDark", isDark.toString());
        applyTheme(isDark);
    });
}

export function DarkModeButton() {
    let isDark = localStorage.getItem("isDark");
    // Create default if not exists
    if (isDark === null) {
        isDark = "false";
        localStorage.setItem("isDark", isDark);
    }
    isDark = isDark === "true";
    // Apply initial theme
    applyTheme(isDark);
    // Create the checkbox input element
    let input = (<input type="checkbox" id="darkModeToggle" className="darkModeToggle" />);
    // If dark mode toggled already, set checkbox to checked
    if (isDark) {
        input = (<input type="checkbox" id="darkModeToggle" defaultChecked className="darkModeToggle" />);
    }
    // Add event listener after a short delay
    setTimeout(() => {
        addEventListener();
    }, 100);
    // Return the JSX for the toggle switch
    return (
        <div className="dark-mode-wrapper">
            <label className="switch">
                {input}
                <span className="slider round"></span>
            </label>
        </div>
    );
}
