// src/Login.js
import { auth, provider, db } from './firebase'; // import db (your Firestore instance)
import { signInWithPopup, signOut } from 'firebase/auth';
import { doc, getDoc } from 'firebase/firestore';
import React, { useState } from 'react';

class AppUser {
    constructor() {
        this.isLoggedIn = false;
        this.email = null;
    }

    checkLoginStatus() {
        return this.isLoggedIn;
    }

    setLoginStatus(status) {
        this.isLoggedIn = status;
    }

    setEmail(email) {
        this.email = email;
    }
}

const user = new AppUser();

const LogIn = ({ setUser }) => {
    const [errorMessage, setErrorMessage] = useState('');

    const handleLogin = async () => {
        setErrorMessage(''); // Clear previous error
        try {
            const result = await signInWithPopup(auth, provider);
            user.setEmail(result.user.email);
            // Fetch allowed emails from Firestore
            const docRef = doc(db, 'allowedEmails', 'chatbot');
            const docSnap = await getDoc(docRef);
            if (docSnap.exists()) {
                const allowedEmails = docSnap.data().emails; // emails is the field
                // check if logged in email is in allowed emails
                if (allowedEmails.includes(user.email)) {
                    setUser(result.user);
                    user.setLoginStatus(true);
                    return;
                }
                signOut(auth);
                setErrorMessage('Your email is not allowed to access this application.');
                return;
            }
            signOut(auth);
            console.error('Could not get allowed users!');
            setErrorMessage('An error occurred, could not get allowed users. Please try again.');
        } catch (error) {
            signOut(auth);
            console.error('Login error', error);
            setErrorMessage('An error occurred during login. Please try again.');
        }
    };

    return (
        <div className="login">
            <h2>Login to access the Chatbot 🤖</h2>
            <button onClick={handleLogin}>🔒 Login with Google 📧</button>
            {errorMessage && <p style={{ color: 'red' }}>{errorMessage}</p>}
        </div>
    );
};

export const Login=LogIn;
export const appUser=user;
