import remarkGfm from "remark-gfm";
import ReactMarkdown from 'react-markdown';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { materialDark } from 'react-syntax-highlighter/dist/esm/styles/prism';
import { useState, useEffect, useCallback, useRef } from 'react';
import { auth } from './firebase';
import { onAuthStateChanged, signOut } from 'firebase/auth';
import { collection, query, where, getDoc, getDocs, addDoc, doc, updateDoc, deleteDoc, arrayUnion, Timestamp, serverTimestamp } from 'firebase/firestore';
import { db } from './firebase';
import { Login, appUser } from './Login';
import { DarkModeButton } from './darkMode';
import './App.css';

const App = () => {
  const [userChats, setUserChats] = useState([]);
  const [activeChatId, setActiveChatId] = useState(null);
  const [userMessage, setUserMessage] = useState('');
  const [chatMessages, setChatMessages] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [loadingMessage, setLoadingMessage] = useState('');
  const [chatbotURL, setChatbotURL] = useState('');
  const [chatbotModel, setChatbotModel] = useState('');
  const [temperature, setTemperature] = useState(0.2);
  const [user, setUser] = useState(null);
  const chatEndRef = useRef(null);
  const collectionName = 'chatBot';
  const typeAsistant = 'asistant';
  const typeUser = 'user';
  const allowedMessageTypes = [typeUser, typeAsistant];
  const numberOfAllowedMessages = 10;
  const fallbackLocation = {lat: null, lon: null};

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      if (appUser.checkLoginStatus()) {
        setUser(currentUser);
      }
    });
    return () => unsubscribe();
  }, []);

  useEffect(() => {
    if (user) {
      scrollToBottomInstantly();
    }
  }, [user]);

  const handleLogout = () => {
    appUser.setLoginStatus(false);
    appUser.setEmail(null);
    signOut(auth);
    setUser(null);
  };

  useEffect(() => {
    const loadChats = async () => {
      if (!user) return;
      const docsQuery = query(collection(db, collectionName), where('owner', '==', appUser.email));
      const snapshot = await getDocs(docsQuery);
      const chats = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
      setUserChats(chats);
    };
    loadChats();
  }, [user, activeChatId]);

  const createNewChat = async (name) => {
    if (!user) return false;
    // max allowed length for name of chat
    if (name.length > 12) name = name.substr(0, 12);
    try {
      const docRef = await addDoc(collection(db, collectionName), {
        owner: appUser.email,
        name: name,
        messages: [],
        createdAt: serverTimestamp()
      });
      setActiveChatId(docRef.id);
      setUserChats(prev => [...prev, { id: docRef.id, name: name, owner: appUser.email, messages: [] }]);
    } catch (error) {
      console.error('Failed to create new chat:', error);
      return false;
    }
    return true;
  };

  const deleteChat = async (chatId) => {
    if (!user) return false;
    try {
      await deleteDoc(doc(db, collectionName, chatId));
      setUserChats(prevChats => prevChats.filter(chat => chat.id !== chatId));
      if (activeChatId === chatId) {
        setActiveChatId(null);
        setChatMessages([]);
      }
      return true;
    } catch (error) {
      console.error('Error deleting chat:', error);
    }
    return false;
  };

  const loadChatMessages = useCallback(async (activeChatId) => {
    if (!activeChatId) return;
    const chatRef = doc(db, collectionName, activeChatId);
    const chatSnap = await getDoc(chatRef);
    if (chatSnap.exists()) {
      setChatMessages(chatSnap.data().messages);
    }
  }, []);

  const scrollToBottom = () => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const scrollToBottomInstantly = () => {
    if (chatEndRef.current) {
      // const container = chatEndRef.current.parentElement;
      // if (container) container.scrollTop = container.scrollHeight; // no animation
      // console.log(container.scrollHeight, container.scrollTop);
      chatEndRef.current.scrollIntoView({ behavior: 'instant' });
    }
  };

  useEffect(() => {
    scrollToBottomInstantly();
  }, [activeChatId]);

  useEffect(() => {
    if (isLoading) return;
    scrollToBottom();
  }, [chatMessages, isLoading]);
  // }, [activeChatId]);

  useEffect(() => {
    scrollToBottom();
  }, []);

  // Load data from localStorage & firebase when the app starts
  useEffect(() => {
    // load fields from session storage
    const savedURL = localStorage.getItem('chatbotURL');
    const savedModel = localStorage.getItem('chatbotModel');
    const savedTemperature = localStorage.getItem('temperature');
    if (savedURL) setChatbotURL(savedURL)
    if (savedModel) setChatbotModel(savedModel);
    if (savedTemperature) setTemperature(parseFloat(savedTemperature));

    // load messages from firebase
    if (user && activeChatId) loadChatMessages(activeChatId);
  }, [user, activeChatId, loadChatMessages]);

  // Save model url to localStorage when it changes
  useEffect(() => {
    localStorage.setItem('chatbotURL', chatbotURL);
  }, [chatbotURL]);

  // Save model to localStorage when it changes
  useEffect(() => {
    localStorage.setItem('chatbotModel', chatbotModel);
  }, [chatbotModel]);

  useEffect(() => {
    localStorage.setItem('temperature', temperature);
  }, [temperature]);

  async function getUserLocation() {
    return new Promise((resolve) => {
      // Check if browser supports geolocation
      if (!navigator.geolocation) {
        console.warn("Geolocation not supported, using fallback.");
        return resolve(fallbackLocation);
      }
      // Get user location
      navigator.geolocation.getCurrentPosition(
        (position) => {
          // ✅ Success
          resolve({
            lat: position.coords.latitude,
            lon: position.coords.longitude
          });
        },
        (error) => {
          // ❌ Permission denied or error
          console.warn("Location denied or unavailable, using fallback.", error);
          resolve(fallbackLocation);
        },
        {
          enableHighAccuracy: true,
          timeout: 5000,
          maximumAge: 600000 // cache for 10 minutes
        }
      );
    });
  };

  async function getCachedLocation() {
    const cached = localStorage.getItem("location");
    // If cached location exists, return it
    if (cached) {
      return JSON.parse(cached);
    }
    // If not, get user location
    const location = await getUserLocation();
    localStorage.setItem("location", JSON.stringify(location));
    // And return it
    return location;
  };

  const buildSystemContext = () => {
    const latestMessages = [];
    // Get last 10 messages only to build context
    const lastMessages = chatMessages.slice(-numberOfAllowedMessages);
    for (const msg of lastMessages) {
      // Only add messages of allowed types and no errors
      if (allowedMessageTypes.includes(msg.type) && !msg.error) {
        latestMessages.push({
          role: String(msg.type),
          content: String(msg.message)
        });
      }
    }
    // Finally return all the messages
    return latestMessages;
  };

  const addMessageToChat = async (chatId, type, message, error = null) => {
    if (!user) return false;
    try {
      const chatRef = doc(db, collectionName, chatId);
      await updateDoc(chatRef, {
        messages: arrayUnion({
          message,
          type,
          error,
          timestamp: Timestamp.now()
        })
      });
      if (type === typeUser || error) {
        setChatMessages((prev) => {
          const updated = [...prev, { type: type, message: message, error: error }];
          return updated;
        });
      }
    }
    catch (error) {
      console.error('Could not add message to chat:', error);
      return false;
    }
    return true;
  };

  const sendMessage = async () => {
    if (!userMessage.trim() || !activeChatId) return;
    scrollToBottom();

    try {
      // Add new message to database
      const messageAdded = await addMessageToChat(activeChatId, typeUser, userMessage);
      if (!messageAdded) throw new Error('Failed to add message into database');
      setUserMessage('');
      setIsLoading(true);
      setLoadingMessage('Thinking...');
      // Get latitude & longitude from user location
      const location = await getCachedLocation();
      // Get response from model
      const response = await fetch(chatbotURL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          latitude: location.lat,
          longitude: location.lon,
          model: chatbotModel,
          prompt: userMessage,
          temperature: temperature,
          user: user.displayName,
          context: buildSystemContext(),
        }),
      });

      if (!response.ok || !response.body) {
        console.log(response.status, await response.text());
        throw new Error('No response body');
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder('utf-8');
      setLoadingMessage('Responding...');
      let responseMessage = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value, { stream: true });
        const lines = chunk.split('\n').filter(line => line.trim() !== '');

        for (const line of lines) {
          const json = JSON.parse(line);
          // Throw an error if "error" key is present
          if (json.error) throw new Error(json.error);
          if (json.done) continue;
          if (json.response) {
            responseMessage += json.response;
            // eslint-disable-next-line no-loop-func
            setChatMessages((prev) => {
              const updated = [...prev];
              if (updated.length > 0 && updated[updated.length - 1].type === typeAsistant) {
                updated[updated.length - 1].message = responseMessage;
              } else {
                updated.push({ type: typeAsistant, message: responseMessage });
              }
              return updated;
            });
          }
        }
      }
      addMessageToChat(activeChatId, typeAsistant, responseMessage);
    }
    catch (error) {
      console.error('Error sending message:', error);
      const errorMessage = error.toString().includes('not found')
        ? '⚠️ Oops! Model name 🧠 not found on this url 🌐!'
        : '⚠️ Something went wrong! The error message is: ' + error.toString();
      // Save the error message
      addMessageToChat(activeChatId, typeAsistant, errorMessage, true);
    }
    finally {
      setIsLoading(false);
      setLoadingMessage('');
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  };

  if (!user) {
    return (
      <div className="app" id="app" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', paddingTop: '50px' }}>
        <DarkModeButton/>
        <Login setUser={setUser} />
      </div>
    );
  }

  return (
    <div className="app" id="app">
      <div className="sidebar">
        <h2>Settings ⚙️</h2>

        <DarkModeButton/>

        <button onClick={handleLogout} className="logout-button">
          Logout🔐
        </button>

        <div className="field chatboturl">
          <label htmlFor="chatbotURL">🌐 Chatbot URL</label>
          <textarea
            id="chatbotURL"
            value={chatbotURL}
            onChange={(e) => setChatbotURL(e.target.value)}
            placeholder="e.g., http://localhost:11434/api/generate"
          />
        </div>

        <div className="field">
          <label htmlFor="chatbotModel">🧠 Chatbot Model</label>
          <textarea
            id="chatbotModel"
            value={chatbotModel}
            onChange={(e) => setChatbotModel(e.target.value)}
            placeholder="e.g., llama3.2"
          />
        </div>

        <div className="field">
          <label htmlFor="temperature">🌡️ Temperature: {temperature}</label>
          <input
            type="range"
            id="temperature"
            min="0"
            max="2"
            step="0.01"
            value={temperature}
            onChange={(e) => setTemperature(parseFloat(e.target.value))}
          />
        </div>

        <div className="field chat-create">
          <h2>Chat Creation ✍️</h2>
          <input
            type="text"
            placeholder="💾 Enter chat name"
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                const name = e.target.value.trim();
                if (name) {
                  createNewChat(name);
                  e.target.value = '';
                }
              }
            }}
            maxLength={12}
          />
        </div>

        <div className="field">
          <h2>Chat List 📜</h2>
          <ul>
            {userChats.map(chat => (
              <li
                key={chat.id}
                style={{ fontWeight: chat.id === activeChatId ? 'bold' : 'normal' }}
              >
                <div>
                  <span
                    onClick={() => {
                      setActiveChatId(chat.id);
                      loadChatMessages(chat.id);
                    }}>
                    💬 {chat.name || '(no name)'}
                  </span>
                  <span
                    className="right-aligned"
                    onClick={() => {deleteChat(chat.id)}}
                  >
                    🗑️
                  </span>
                </div>
              </li>
            ))}
          </ul>
        </div>
      </div>

      <div className="main">
        <h1>My Chatbot 🤖</h1>

        <div className="chat-box">
          {chatMessages.map((msg, index) => (
            <div 
              key={index}
              className={`message ${msg.type}`}
              style={msg.error ? { backgroundColor: '#f3e050' } : {}}
            >
              <ReactMarkdown
                remarkPlugins={[remarkGfm]}
                components={{
                  code({ node, inline, className, children, ...props }) {
                    const match = /language-(\w+)/.exec(className || '');
                    const codeText = String(children).replace(/\n$/, '');
                    return !inline && match ? (
                      <div className='markdown'>
                        <SyntaxHighlighter
                          style={materialDark}
                          language={match[1]}
                          PreTag="div"
                          {...props}
                        >
                          {String(children).replace(/\n$/, '')}
                        </SyntaxHighlighter>
                        <span className="clipboard" onClick={() => navigator.clipboard.writeText(codeText)}>📋</span>
                      </div>
                    ) : (
                      <code className={className} {...props}>
                        {children}
                      </code>
                    );
                  }
                }}
              >
                {msg.type === typeUser ? '🧑‍💻 ' + msg.message :'🤖 ' + msg.message}
              </ReactMarkdown>
              {msg.type === typeUser && (<span className="copyboard" onClick={() => navigator.clipboard.writeText(msg.message)}>📋</span>)}
            </div>
          ))}
          {isLoading && <p className="loading">{loadingMessage}</p>}
          <div ref={chatEndRef} />
        </div>

        <div className="input-area">
          <textarea
            value={userMessage}
            onChange={(e) => setUserMessage(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Type a message... ✒️"
            rows={2} // you can adjust this
            style={{ resize: 'vertical' }} // optional: allow resizing
          />
          <button onClick={sendMessage} disabled={isLoading}>
            Send ✉️
          </button>
        </div>
      </div>
    </div>
  );
};

export default App;
